SELECT DATETIME, NANO100_BETWEEN(LAG(DATETIME, 1) OVER (ORDER BY DATETIME), DATETIME)/10000000 AS TIEMPO, OBJECT, TEXT, VALUE 
FROM EXT.CSE_LOG
WHERE 1=1
	AND	DATETIME > '2025-05-29 11:44:12' -- Poner hora de inicio de ejecución
	-- AND	DATETIME < '2025-05-29 11:44:56' 
	AND OBJECT LIKE '%SP_CREAR_TABLAS%'
	-- AND VALUE = 2 -- Para saber el mes
	-- AND (TEXT LIKE '%Marzo 2025%' OR TEXT LIKE '%Abril 2025%')
ORDER BY DATETIME DESC
